{"file_path":"src/errors.js","content":"/**
 * The error types the CLI can raise. `code` is the process exit code and
 * `message` is the full line (including the `error: ` prefix) to write to
 * standard error.
 */

export class AppError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

export class CycleError extends AppError {
  constructor(names) {
    super(`error: cycle: ${names.join(' -> ')}`, 3)
    this.names = names
  }
}
"}

