{"file_path":"src/parse.js","content":"/**
 * Parses a build graph out of the CLI's standard input text.
 */

import { AppError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

function usageless(message) {
  return new AppError(`error: ${message}`, 2)
}

function checkName(name, line) {
  if (!NAME_RE.test(name)) {
    throw usageless(`line ${line}: invalid task name ${name}`)
  }
}

/**
 * Splits the raw CLI input into trimmed, numbered lines, skipping blanks
 * and comments. Each entry is `{ line, words }`.
 */
function tokenizeLines(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }
  const entries = []
  rawLines.forEach((raw, index) => {
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    entries.push({ line: index + 1, words: trimmed.split(/\s+/) })
  })
  return entries
}

/**
 * Parses the input into a graph: `tasks` maps name to cost, `deps` maps
 * name to the `Set` of names it depends on (only present for names that
 * appear as a `dep` line's target).
 */
export function parseGraph(input) {
  const tasks = new Map()
  const deps = new Map()
  const depLines = []

  for (const { line, words } of tokenizeLines(input)) {
    const directive = words[0]
    if (directive === 'task') {
      if (words.length !== 3) {
        throw usageless(`line ${line}: expected task <name> <cost>`)
      }
      const [, name, cost] = words
      checkName(name, line)
      if (!COST_RE.test(cost)) {
        throw usageless(`line ${line}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw usageless(`line ${line}: task ${name} is declared twice`)
      }
      tasks.set(name, Number.parseInt(cost, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw usageless(`line ${line}: expected dep <name> <dependency>...`)
      }
      const [, target, ...dependencies] = words
      checkName(target, line)
      for (const dependency of dependencies) checkName(dependency, line)
      depLines.push({ target, dependencies })
    } else {
      throw usageless(`line ${line}: unknown directive ${directive}`)
    }
  }

  for (const { target, dependencies } of depLines) {
    for (const name of [target, ...dependencies]) {
      if (!tasks.has(name)) {
        throw usageless(`unknown task ${name}`)
      }
    }
    let set = deps.get(target)
    if (!set) {
      set = new Set()
      deps.set(target, set)
    }
    for (const dependency of dependencies) set.add(dependency)
  }

  return { tasks, deps }
}
"}

