{"file_path":"src/graph.js","content":"/**
 * Cycle detection and the unlimited-worker schedule (waves, start/finish
 * times) shared by the `waves` and `explain` commands.
 */

import { CycleError } from './errors.js'

function sortedDeps(deps, name) {
  const set = deps.get(name)
  return set ? [...set].sort() : []
}

/**
 * Throws a `CycleError` if the graph has a cycle. The search starts from
 * each task in ascending name order and walks dependencies in ascending
 * name order, reporting the first cycle it re-enters.
 */
export function checkForCycle(tasks, deps) {
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function visit(name) {
    stack.push(name)
    onStack.add(name)
    for (const dependency of sortedDeps(deps, name)) {
      if (onStack.has(dependency)) {
        const start = stack.indexOf(dependency)
        throw new CycleError([...stack.slice(start), dependency])
      }
      if (!visited.has(dependency)) visit(dependency)
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!visited.has(name)) visit(name)
  }
}

/**
 * Computes, for every task, its `start`, `finish` and `depth` (the wave it
 * sits in) assuming unlimited workers. Requires the graph to be acyclic.
 */
export function computeSchedule(tasks, deps) {
  const info = new Map()

  function resolve(name) {
    const cached = info.get(name)
    if (cached) return cached
    let start = 0
    let depth = 0
    for (const dependency of sortedDeps(deps, name)) {
      const dependencyInfo = resolve(dependency)
      if (dependencyInfo.finish > start) start = dependencyInfo.finish
      if (dependencyInfo.depth + 1 > depth) depth = dependencyInfo.depth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    info.set(name, result)
    return result
  }

  for (const name of tasks.keys()) resolve(name)
  return info
}

/** The makespan with unlimited workers: the greatest finish, or 0. */
export function totalOf(schedule) {
  let total = 0
  for (const { finish } of schedule.values()) {
    if (finish > total) total = finish
  }
  return total
}
"}

