{"file_path":"src/pack.js","content":"/**
 * The `pack <workers>` simulation: schedules the graph onto a fixed number
 * of workers, greedily preferring the task with the longest remaining
 * chain of costs.
 */

/**
 * Builds, for every task, the cost of the longest chain of costs starting
 * at it and running down through its dependents to a task nothing depends
 * on. Requires the graph to be acyclic.
 */
function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [target, set] of deps) {
    for (const dependency of set) dependents.get(dependency).push(target)
  }

  const priority = new Map()
  function resolve(name) {
    const cached = priority.get(name)
    if (cached !== undefined) return cached
    let best = 0
    for (const dependent of dependents.get(name)) {
      const dependentPriority = resolve(dependent)
      if (dependentPriority > best) best = dependentPriority
    }
    const result = tasks.get(name) + best
    priority.set(name, result)
    return result
  }

  for (const name of tasks.keys()) resolve(name)
  return priority
}

/**
 * Runs the simulation and returns `{ workers, makespan }`, where `workers`
 * is an array of per-worker `{ name, start, finish }` run lists in start
 * order.
 */
export function packSchedule(tasks, deps, workerCount) {
  const priority = computePriorities(tasks, deps)
  const finishOf = new Map()
  const remaining = new Set(tasks.keys())
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, runs: [] }))
  let currentTime = 0

  const isReady = (name) => {
    const dependencies = deps.get(name)
    if (!dependencies) return true
    for (const dependency of dependencies) {
      const finish = finishOf.get(dependency)
      if (finish === undefined || finish > currentTime) return false
    }
    return true
  }

  while (remaining.size > 0) {
    const freeWorker = workers.findIndex((worker) => worker.freeAt <= currentTime)
    const ready = [...remaining].filter(isReady)

    if (freeWorker === -1 || ready.length === 0) {
      let next = Infinity
      for (const worker of workers) {
        if (worker.freeAt > currentTime && worker.freeAt < next) next = worker.freeAt
      }
      currentTime = next
      continue
    }

    ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : 1))
    const name = ready[0]
    const start = currentTime
    const finish = start + tasks.get(name)
    workers[freeWorker].runs.push({ name, start, finish })
