  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new AppError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: Number.parseInt(argv[1], 10) }
  }
  throw new AppError(USAGE, 2)
}

function renderWaves(schedule) {
  const byDepth = new Map()
  for (const [name, { depth }] of schedule) {
    if (!byDepth.has(depth)) byDepth.set(depth, [])
    byDepth.get(depth).push(name)
  }
  const lines = []
  for (const depth of [...byDepth.keys()].sort((a, b) => a - b)) {
    lines.push(`wave ${depth}: ${byDepth.get(depth).sort().join(' ')}`)
  }
  lines.push(`total ${totalOf(schedule)}`)
  return lines.map((line) => `${line}\n`).join('')
}

function renderExplain(tasks, schedule) {
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    const { start, finish, depth } = schedule.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  lines.push(`total ${totalOf(schedule)}`)
  return lines.map((line) => `${line}\n`).join('')
}

function renderPack({ workers, makespan }) {
  const lines = workers.map((worker, index) => {
    const runs = worker.runs.map(({ name, start, finish }) => ` ${name}@${start}-${finish}`).join('')
    return `worker ${index}:${runs}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.map((line) => `${line}\n`).join('')
}

function main() {
  let args
  try {
    args = parseArgs(process.argv.slice(2))
  } catch (error) {
    if (error instanceof AppError) {
      process.stderr.write(`${error.message}\n`)
      process.exit(error.code)
    }
    throw error
  }

  const input = fs.readFileSync(0, 'utf8')

  try {
    const { tasks, deps } = parseGraph(input)
    checkForCycle(tasks, deps)

    if (args.mode === 'waves') {
      process.stdout.write(renderWaves(computeSchedule(tasks, deps)))
    } else if (args.mode === 'explain') {
      process.stdout.write(renderExplain(tasks, computeSchedule(tasks, deps)))
    } else {
      process.stdout.write(renderPack(packSchedule(tasks, deps, args.workers)))
    }
  } catch (error) {
    if (error instanceof AppError) {
      process.stderr.write(`${error.message}\n`)
      process.exit(error.code)
    }
    throw error
  }
}

main()
